const selectPanel=history=>{$('event-current-panel').hidden=history;$('event-history-panel').hidden=!history;$('event-current-tab').setAttribute('aria-pressed',String(!history));$('event-history-tab').setAttribute('aria-pressed',String(history));};
$('event-current-tab').onclick=()=>selectPanel(false);$('event-history-tab').onclick=()=>selectPanel(true);selectPanel(keepHistory);
